d": "f484ce06-9e21-43c3-b09f-ff1c27dac791", "type": "subtopic", "title": "Scale and abstraction", "children": [{"id": "26600b0a-fb4c-4e84-b462-a4e0915dd045", "type": "concept", "title": "Figure, room, building, site, urban, and detail scales"}, {"id": "b6081e53-80e5-4f66-af6f-2d41f2dabe2e", "type": "concept", "title": "Omission, simplification, emphasis, and graphic consistency"}, {"id": "3ee23fe1-873c-45bc-83b9-dab954e31f76", "type": "concept", "title": "Drawing as spatial reasoning"}], "description": "Students decide what to show at each scale."}]}, {"id": "8c3d14b4-1ef9-4464-b666-600590b89792", "type": "topic", "title": "Observation, Visual Notes, Measured Drawing, Field Sketching, and Spatial Documentation", "description": "This module builds the habit of looking carefully and recording existing space, material, movement, proportion, and atmosphere with speed and accuracy.", "children": [{"id": "0f1b443b-0f63-462b-a627-2aa0a1180a16", "type": "subtopic", "title": "Field sketching", "children": [{"id": "6250e817-ac6c-4bfd-8692-50d33c776fdb", "type": "concept", "title": "Gesture, contour, proportion, perspective, material, light, and movement"}, {"id": "94456b16-0dda-4016-93b4-b05d49f61795", "type": "concept", "title": "Capturing experience without overworking the page"}, {"id": "e03894e8-0af6-428d-bc6f-f54a01984945", "type": "concept", "title": "Sketchbooks as design instruments"}], "description": "Students build speed and judgment by drawing from real environments."}, {"id": "b42e2664-17b8-48bc-adcd-b356fcba24fa", "type": "subtopic", "title": "Measured drawing", "children": [{"id": "cf8ea63b-a895-4141-a521-088b8bde60bd", "type": "concept", "title": "Baseline dimensions, grid, datum, openings, furniture, site features, and annotation"}, {"id": "8f7da7c6-fffd-4a24-b1b0-130022e61e3f", "type": "concept", "title": "Plans, sections, elevations, and detail notes from field conditions"}, {"id": "316e8812-793a-40eb-bee0-7f5a3afcf859", "type": "concept", "title": "Accuracy versus interpretation"}], "description": "The gist is to turn observation into reliable spatial evidence."}, {"id": "1b985c94-126d-4191-bbee-496824d922f9", "type": "subtopic", "title": "Visual notes", "children": [{"id": "a325397a-eaaf-41bd-aabb-9902f25cc080", "type": "concept", "title": "Diagrammatic notes, callouts, arrows, fragments, color coding, and comparison sketches"}, {"id": "950c0361-1d96-4e28-8c69-fc7207de1e54", "type": "concept", "title": "Observational, analytical, and speculative notes"}, {"id": "e4da68c1-a56d-4067-b6c5-f346ccf19288", "type": "concept", "title": "Studio notebooks and iterative thinking"}], "description": "Students learn to record ideas before they disappear."}]}, {"id": "254b8914-6de6-4c53-8fcb-c28dd6834374", "type": "topic", "title": "Orthographic and Sectional Representation: Plans, Sections, Elevations, Axonometrics, and Obliques", "description": "Students deepen architectural drawing conventions so technical views become tools for design thinking rather than merely required outputs.", "children": [{"id": "2963eab7-1d04-4360-9924-b6d7ad6901ab", "type": "subtopic", "title": "Orthographic conventions", "children": [{"id": "c2a1d377-008a-4b62-a420-01adda53b6f4", "type": "concept", "title": "Plans, sections, elevations, reflected ceiling plans, and site plans"}, {"id": "f761787e-5c2e-4c3f-92f6-7ba3f5d6b6bb", "type": "concept", "title": "Cut planes, projection alignment, scale, north arrows, titles, and references"}, {"id": "7ddc9bfd-a741-43a5-bb2d-d8d7de14aef4", "type": "concept", "title": "Drawing standards and design clarity"}], "description": "Students refine the core architectural drawing set."}, {"id": "ec07af8b-9b69-44d0-99e8-be5ca5d624df", "type": "subtopic", "title": "Sectional thinking", "children": [{"id": "bbde7333-876e-4407-858f-9369817f744e", "type": "concept", "title": "Spatial sequence, structure, ground, light, envelope, occupation, and threshold"}, {"id": "e0918608-626b-41f6-8e74-226db4eb09eb", "type": "concept", "titl