set
  title = 'Visual Representation II / Drawing II',
  goal = 'Visual Representation II / Drawing II',
  summary = 'Students sharpen drawing as a design instrument, using line, tone, scale, projection, observation, diagrams, collage, rendering, photography, and hybrid analog-digital workflows to test and communicate architectural ideas with graphic clarity and ethical judgment.',
  data = $vr2json${"slug": "visual-representation-ii-drawing-ii", "title": "Visual Representation II / Drawing II", "description": "Students sharpen drawing as a design instrument, using line, tone, scale, projection, observation, diagrams, collage, rendering, photography, and hybrid analog-digital workflows to test and communicate architectural ideas with graphic clarity and ethical judgment.", "topics": [{"id": "e471b724-4478-4f0c-a4b0-e694df4d4d7c", "type": "topic", "title": "Advanced Architectural Drawing: Line, Tone, Projection, Scale, and Spatial Thinking", "description": "Students sharpen drawing as a design instrument, using line, tone, scale, projection, and spatial judgment to test and communicate architectural ideas.", "children": [{"id": "68558af4-83ef-4847-b726-da2f80effb75", "type": "subtopic", "title": "Line as information", "children": [{"id": "1a3624ac-eab3-4ecb-a387-904f40dc5eba", "type": "concept", "title": "Profile, cut, surface, hidden, construction, poche, and entourage lines"}, {"id": "4f625420-073a-40c8-b78e-e5e195093377", "type": "concept", "title": "Line weight systems for plans, sections, elevations, and diagrams"}, {"id": "a5e001d0-d187-488b-aa5e-2fe10d3e93bb", "type": "concept", "title": "Clarity, economy, and intentional imperfection"}], "description": "Students learn to use line quality as a hierarchy of space, material, edge, depth, and emphasis."}, {"id": "ec0e6c65-2c38-4fbd-970a-551726ce8b5a", "type": "subtopic", "title": "Tone and depth", "children": [{"id": "44aa9951-156d-47ed-954a-287952e387e8", "type": "concept", "title": "Hatching, stippling, wash, graphite, ink, marker, and digital tone"}, {"id": "0ca5ed3d-e9a1-4c8a-a94b-6d65c9406f06", "type": "concept", "title": "Foreground, middle ground, background, and depth cues"}, {"id": "1b4ecf5b-483c-4bb0-946f-f0def9f16c47", "type": "concept", "title": "Contrast, value range, and legibility"}], "description": "The point is to make flat drawings communicate spatial order and atmosphere."}, {"id": "f484ce06-9e21-43c3-b09f-ff1c27dac791", "type": "subtopic", "title": "Scale and abstraction", "children": [{"id": "26600b0a-fb4c-4e84-b462-a4e0915dd045", "type": "concept", "title": "Figure, room, building, site, urban, and detail scales"}, {"id": "b6081e53-80e5-4f66-af6f-2d41f2dabe2e", "type": "concept", "title": "Omission, simplification, emphasis, and graphic consistency"}, {"id": "3ee23fe1-873c-45bc-83b9-dab954e31f76", "type": "concept", "title": "Drawing as spatial reasoning"}], "description": "Students decide what to show at each scale."}]}, {"id": "8c3d14b4-1ef9-4464-b666-600590b89792", "type": "topic", "title": "Observation, Visual Notes, Measured Drawing, Field Sketching, and Spatial Documentation", "description": "This module builds the habit of looking carefully and recording existing space, material, movement, proportion, and atmosphere with speed and accuracy.", "children": [{"id": "0f1b443b-0f63-462b-a627-2aa0a1180a16", "type": "subtopic", "title": "Field sketching", "children": [{"id": "6250e817-ac6c-4bfd-8692-50d33c776fdb", "type": "concept", "title": "Gesture, contour, proportion, perspective, material, light, and movement"}, {"id": "94456b16-0dda-4016-93b4-b05d49f61795", "type": "concept", "title": "Capturing experience without overworking the page"}, {"id": "e03894e8-0af6-428d-bc6f-f54a01984945", "type": "concept", "title": "Sketchbooks as design instruments"}], "description": "Students build speed and judgment by drawing from real environments."}, {"id": "b42e2664-17b8-48bc-adcd-b356fcba24fa", "type": "subtopic", "title": "Measured drawing", "children": [{"id": "cf8ea63b-a895-4141-a521-088b8bde60bd", "type": "concept", "title": "Baseline dimensions, grid, datum, openings, furniture, site features, and annotation"}, {"id": "8f7da7c6-fffd-4a24-b1b0-130022e61e3f", "type": "concept", "title": "Plans, sections, elevations, and detail notes from field conditions"}, {"id": "316e8812-793a-40eb-bee0-7f5a3afcf859", "type": "concept", "title": "Accuracy versus interpretation"}], "description": "The gist is to turn observation into reliable spatial evidence."}, {"id": "1b985c94-126d-4191-bbee-496824d922f9", "type": "subtopic", "title": "Visual notes", "children": [{"id": "a325397a-eaaf-41bd-aabb-9902f25cc080", "type": "concept", "title": "Diagrammatic notes, callouts, arrows, fragments, color coding, and comparison sketches"}, {"id": "950c0361-1d96-4e28-8c69-fc7207de1e54", "type": "concept", "title": "Observational, analytical, and speculative notes"}, {"id": "e4da68c1-a56d-4067-b6c5-f346ccf19288", "type": "concept", "title": "Studio notebooks and iterative thinking"}], "description": "Students learn to record ideas before they disappear."}]}, {"id": "254b8914-6de6-4c53-8fcb-c28dd6834374", "type": "topic", "title": "Orthographic and Sectional Representation: Plans, Sections, Elevations, Axonometrics, and Obliques", "description": "Students deepen architectural drawing conventions so technical views become tools for design thinking rather than merely required outputs.", "children": [{"id": "2963eab7-1d04-4360-9924-b6d7ad6901ab", "type": "subtopic", "title": "Orthographic conventions", "children": [{"id": "c2a1d377-008a-4b62-a420-01adda53b6f4", "type": "concept", "title": "Plans, sections, elevations, reflected ceiling plans, and site plans"}, {"id": "f761787e-5c2e-4c3f-92f6-7ba3f5d6b6bb", "type": "concept", "title": "Cut planes, projection alignment, scale, north arrows, titles, and references"}, {"id": "7ddc9bfd-a741-43a5-bb2d-d8d7de14aef4", "type": "concept", "title": "Drawing standards and design clarity"}], "description": "Students refine the core architectural drawing set."}, {"id": "ec07af8b-9b69-44d0-99e8-be5ca5d624df", "type": "subtopic", "title": "Sectional thinking", "children": [{"id": "bbde7333-876e-4407-858f-9369817f744e", "type": "concept", "title": "Spatial sequence, structure, ground, light, envelope, occupation, and threshold"}, {"id": "e0918608-626b-41f6-8e74-226db4eb09eb", "type": "concept", "title": "Section-perspective and sectional axonometric"}, {"id": "80b23f49-b180-4f80-8610-afbe458500dc", "type": "concept", "title": "Poche, depth, and atmosphere"}], "description": "The point is to use section as a design tool, not just a documentation requirement."}, {"id": "f9ae52ed-9d23-4ce2-bd7e-56f08a6f528b", "type": "subtopic", "title": "Axonometric and oblique drawing", "children": [{"id": "b37e98b4-a7c5-4b5e-a218-b16f2f28625d", "type": "concept", "title": "Isometric, axonometric, exploded axonometric, worm's-eye, and oblique views"}, {"id": "8deda39d-ab34-4b4f-8124-e0beb12a7f62", "type": "concept", "title": "Assembly, circulation, structure, and massing diagrams"}, {"id": "9acac973-924c-4cce-a8f3-fdaa9b024a41", "type": "concept", "title": "Layering and selective transparency"}], "description": "Students communicate assemblies and spatial relationships without perspective distortion."}]}, {"id": "07f22ff3-fd6c-4dc9-93ef-6a2df1a6b130", "type": "topic", "title": "Perspective, Constructed Views, Figure, Entourage, and Experiential Scene Making", "description": "This topic trains students to construct convincing spatial views that communicate scale, use, atmosphere, and human experience.", "children": [{"id": "fd4e153f-1124-4648-8649-448d77f09849", "type": "subtopic", "title": "Constructed perspective", "children": [{"id": "390c3353-4606-41b8-b974-deb3578713fb", "type": "concept", "title": "One-point, two-point, three-point, measured perspective, and section perspective"}, {"id": "46ddab48-43f8-4aae-af3b-6143a07899a9", "type": "concept", "title": "Horizon line, station point, cone of vision, and view framing"}, {"id": "6a0f4020-d344-4f70-a1cd-8f58f86dd380", "type": "concept", "title": "Interior, exterior, and urban views"}], "description": "Students learn reliable systems for visualizing space."}, {"id": "b2874004-6a47-4f1e-9ef2-ead9358aa71e", "type": "subtopic", "title": "Figure and entourage", "children": [{"id": "ba36af24-6749-43db-b2be-25ea09834523", "type": "concept", "title": "Human figures, furniture, planting, vehicles, animals, weather, and activity"}, {"id": "f9d9cd29-a467-43a2-bd6e-1b38c3b70e62", "type": "concept", "title": "Silhouette, posture, movement, and social use"}, {"id": "cc53e6d8-3d2d-433e-8b0d-0a2c5098b48c", "type": "concept", "title": "Ethics of representation and inclusivity"}], "description": "The gist is to communicate scale and use without letting entourage overwhelm architecture."}, {"id": "05c36e05-b303-4ce6-8770-50f4f6c23a5b", "type": "subtopic", "title": "Experiential composition", "children": [{"id": "8caaa12d-9a20-4c24-ba4d-c9afcda2d6aa", "type": "concept", "title": "Approach, threshold, compression, release, light, sound, texture, and material presence"}, {"id": "569cfbef-6039-4047-9857-f43005aab746", "type": "concept", "title": "Camera height and focal length decisions"}, {"id": "724f3c07-728d-4480-b588-3b169bd430b5", "type": "concept", "title": "Atmosphere as evidence of design intent"}], "description": "Students make views that tell a spatial story."}]}, {"id": "4d4a2d81-c6da-43b8-a87f-4d340cfcd695", "type": "topic", "title": "Hybrid Analog-Digital Workflows: Scanning, Layering, Vector/Raster Editing, and Iteration", "description": "Students learn to move fluidly between hand drawing and digital media while preserving authorship, experimentation, and clarity.", "children": [{"id": "b5b74b51-8d04-48e4-8c00-19b40f0b97df", "type": "subtopic", "title": "Analog capture", "children": [{"id": "812620ff-66dd-455a-ad7f-57f4ff0ff1e2", "type": "concept", "title": "Scanning, photographing, cleaning, thresholding, and color correction"}, {"id": "e1736f04-7ec6-4674-bfd8-7758bbfe6620", "type": "concept", "title": "Paper texture, line fidelity, and resolution"}, {"id": "2318f180-1433-4aa4-af18-00f96bff602f", "type": "concept", "title": "Naming, archiving, and versioning scans"}], "description": "Students learn to preserve the intelligence of hand work in digital workflows."}, {"id": "d98934b5-d535-4c2a-aeef-f4956a0cd1ad", "type": "subtopic", "title": "Digital layering", "children": [{"id": "ac3e6dba-12f4-4226-965c-9d9014e26803", "type": "concept", "title": "Photoshop, Illustrator, InDesign, CAD/PDF exports, masks, blend modes, and transparency"}, {"id": "0a928cad-694a-4c37-9882-6c10aff0246e", "type": "concept", "title": "Vector versus raster decisions"}, {"id": "32b3a8a9-c790-41b9-b0ec-734670b576d3", "type": "concept", "title": "Non-destructive editing habits"}], "description": "The point is to combine hand, CAD, model, image, and text layers coherently."}, {"id": "8b0a3ab7-29b9-4246-94f9-30afa60edbab", "type": "subtopic", "title": "Iterative workflow", "children": [{"id": "e94dc822-1076-442b-a4ca-ad9062008576", "type": "concept", "title": "Redlining, overlays, alternatives, feedback cycles, and process boards"}, {"id": "bb01db8a-c5b1-4eb8-8b20-69f00014502b", "type": "concept", "title": "Analog-digital-analog loops"}, {"id": "04734841-b5f0-4f39-a7c4-cf5aa40bc580", "type": "concept", "title": "Speed, clarity, and craft under studio deadlines"}], "description": "Students keep representation tied to design development."}]}, {"id": "d07da44a-02de-4672-8722-7fa241094868", "type": "topic", "title": "Diagrams and Process Drawing: Concept, Circulation, Program, Systems, and Design Research", "description": "This module treats diagrams as arguments: visual tools for discovering, testing, and explaining relationships in a project.", "children": [{"id": "aa67d0f8-0a91-48fb-a438-ea10b3d54658", "type": "subtopic", "title": "Concept diagrams", "children": [{"id": "170acd42-d3a7-4434-bfc3-d84fb982f224", "type": "concept", "title": "Parti, massing, field, axis, grid, figure-ground, and organizational diagrams"}, {"id": "82aad78e-67ec-4acb-a34c-c3f352fa9207", "type": "concept", "title": "Abstraction and reduction"}, {"id": "dec1241c-a2a3-4dd8-9b83-6206b1a62ee7", "type": "concept", "title": "Diagram as claim, not decoration"}], "description": "Students learn to explain the governing idea of a project visually."}, {"id": "40b879dc-aa47-43ed-be6a-85e7e7b3c1e1", "type": "subtopic", "title": "Program and circulation diagrams", "children": [{"id": "d6ea19ac-a244-46ff-aa4c-f8f4cefcf37b", "type": "concept", "title": "Adjacency, hierarchy, public/private gradients, movement, access, and thresholds"}, {"id": "c185bc41-f4fa-4192-86db-7769cb048800", "type": "concept", "title": "User groups, time, events, and conflicts"}, {"id": "26a9dbab-aa2c-4742-8526-8bdf0f86edd4", "type": "concept", "title": "Comparative options and decision diagrams"}], "description": "The gist is to show relationships that plans alone may hide."}, {"id": "6ce10362-3312-43c6-acea-80228b8dadfa", "type": "subtopic", "title": "Process drawing", "children": [{"id": "c9c50d52-f3fa-4d60-bb5c-6501da6f8c8f", "type": "concept", "title": "Iteration sequences, overlays, transformation diagrams, precedent analysis, and critique response"}, {"id": "08ae91dd-79ee-4167-9fd5-2bc9f34a2e43", "type": "concept", "title": "Research through drawing"}, {"id": "ef6b598f-bda7-460e-84d7-17cffbef21f2", "type": "concept", "title": "Documentation of why a design changed"}], "description": "Students make design thinking visible."}]}, {"id": "c936fae5-6bdd-4be2-ab49-9898c2c5a7eb", "type": "topic", "title": "Conceptual Collage, Assemblage, Mixed Media, Narrative, and Speculative Representation", "description": "Students explore collage and mixed media as ways to combine context, atmosphere, memory, precedent, program, and design speculation.", "children": [{"id": "0f2956b1-4108-4901-9ae6-f9d81fd01009", "type": "subtopic", "title": "Collage grammar", "children": [{"id": "e63ea3b7-d223-4321-aba7-dd5a8e073916", "type": "concept", "title": "Cut, scale shift, juxtaposition, transparency, repetition, texture, and montage"}, {"id": "f0cd95c1-1265-4b44-be20-d993903b14a9", "type": "concept", "title": "Foreground/background and visual tension"}, {"id": "3b96f118-4107-4364-98a2-579cc46a41d9", "type": "concept", "title": "Analog and digital collage techniques"}], "description": "Students learn how fragments produce meaning."}, {"id": "c1351fef-9c0a-4606-a749-98b6ec9af2ac", "type": "subtopic", "title": "Narrative and atmosphere", "children": [{"id": "426a6ecf-519a-4cea-aa7d-c1628adac804", "type": "concept", "title": "Storyboarding, speculative scenes, material mood, cultural context, and memory"}, {"id": "82138d0a-16aa-433d-a317-93ca797f819f", "type": "concept", "title": "Time, weather, occupation, and change"}, {"id": "d3b042fa-0824-48f2-91e4-d73be2d6d9a8", "type": "concept", "title": "Avoiding empty mood-board aesthetics"}], "description": "The point is to represent possible worlds and design intentions."}, {"id": "d6d52e49-cd6a-4540-9df9-355c5433ae2f", "type": "subtopic", "title": "Mixed-media experimentation", "children": [{"id": "8dc48784-03dc-4c6e-9504-df21999ac7f5", "type": "concept", "title": "Graphite, charcoal, ink, pastel, colored pencil, print, photography, transfer, paint, and digital overlays"}, {"id": "4df2bb0e-3191-4523-a69f-798082d8c5ff", "type": "concept", "title": "Large-scale drawing and installation-like presentation"}, {"id": "ef029ad8-00fd-4089-9c34-8ae2d5da15bb", "type": "concept", "title": "Material choices as conceptual decisions"}], "description": "Students expand the representational palette."}]}, {"id": "e3c82477-4e9a-4cbb-abc2-446225cae36c", "type": "topic", "title": "Rendering Techniques: Light, Shadow, Material, Color, Texture, Atmosphere, and Post-Production", "description": "This topic develops rendering judgment across hand, digital, and hybrid techniques, emphasizing legibility, mood, materiality, and restraint.", "children": [{"id": "28d397c9-2c37-41cc-99e5-2eaad4b0286f", "type": "subtopic", "title": "Light and shadow", "children": [{"id": "16711f3c-323f-4d0a-a621-ed651361f864", "type": "concept", "title": "Sun angle, artificial light, ambient light, cast shadow, shade, reflection, and glow"}, {"id": "46359469-124d-4847-a001-2e9c4009f25e", "type": "concept", "title": "Value structure and focus"}, {"id": "f50c8403-57e5-479b-b342-1237f1fca147", "type": "concept", "title": "Day/night and seasonal conditions"}], "description": "Students learn that rendering begins with light logic."}, {"id": "c3deee3b-0c0a-45f7-8849-79c2483d713a", "type": "subtopic", "title": "Material and color", "children": [{"id": "f566121e-4462-4096-a03c-140663c3e345", "type": "concept", "title": "Wood, concrete, brick, metal, glass, fabric, vegetation, water, and ground"}, {"id": "395bccbb-0f0d-4ec6-9e9d-83d7a4521f79", "type": "concept", "title": "Texture scale, bump, reflection, color temperature, and weathering"}, {"id": "10a128b7-f63e-4fa0-b5f3-24018637cad8", "type": "concept", "title": "Color palettes and restraint"}], "description": "The gist is to communicate material character without visual clutter."}, {"id": "4abd5e55-0f49-4604-84ee-d51738b35e03", "type": "subtopic", "title": "Post-production", "children": [{"id": "ca37891e-17f6-458a-92f0-78a8b63ad453", "type": "concept", "title": "Compositing, masks, entourage, atmosphere, correction, sharpening, noise, and output size"}, {"id": "34d864f7-de87-41e4-9a84-c16b9c146ef3", "type": "concept", "title": "Rendering over model exports and linework"}, {"id": "c1218e88-baa0-41e1-9cbe-9c6d9c284953", "type": "concept", "title": "Avoiding deceptive or overproduced images"}], "description": "Students refine images for clarity and argument."}]}, {"id": "5b9f201e-028b-4ff6-a73e-b59d451bb26b", "type": "topic", "title": "Photography for Architects: Site, Model, Process, Precedent, and Image Editing", "description": "Students learn photography as a representation tool for documenting site, models, materials, process, and final work.", "children": [{"id": "acc5525d-19b6-431d-8866-d2c52e51ba0c", "type": "subtopic", "title": "Site photography", "children": [{"id": "6a136e5a-aa4f-4b2b-9207-cec808578390", "type": "concept", "title": "Light, view sequence, approach, use patterns, materials, edges, and details"}, {"id": "c83c11df-add9-43b7-a2b0-42d09917ca52", "type": "concept", "title": "Panoramas, serial views, and photo maps"}, {"id": "513b2975-5ffc-452e-bf7b-8c729b2f776c", "type": "concept", "title": "Metadata, captions, and source discipline"}], "description": "Students learn to document context as evidence."}, {"id": "6e2c81b8-2d90-4221-90e3-85c6241575d5", "type": "subtopic", "title": "Model and process photography", "children": [{"id": "cb3afa2e-7294-4f88-80f7-d4e1edb9fe97", "type": "concept", "title": "Lighting setup, background, focus, depth of field, scale figures, and shadows"}, {"id": "01d3a439-90ff-43c9-9960-c60dddd9e763", "type": "concept", "title": "Process documentation and iteration records"}, {"id": "7665a4e9-ff32-4536-8d7d-d31fc97cc411", "type": "concept", "title": "Cropping and file management"}], "description": "The point is to make physical work legible in critique and portfolio."}, {"id": "4722713c-632e-41f0-a2cf-704dcac24df4", "type": "subtopic", "title": "Image editing", "children": [{"id": "a5a0d379-9670-4f27-8b7c-4f51ba409b15", "type": "concept", "title": "Exposure, white balance, perspective correction, cleanup, color, and sequencing"}, {"id": "23dfa2ed-8b85-49c9-abdf-7881bef6b33d", "type": "concept", "title": "Composite reference images and site overlays"}, {"id": "3f4a240f-b541-4ecd-960e-e744f1e06d78", "type": "concept", "title": "Ethical limits of manipulation"}], "description": "Students edit photographs responsibly for representation."}]}, {"id": "2674425e-f114-410e-8163-376846a3e542", "type": "topic", "title": "Digital Modeling to Drawing: Geometry, Views, Exports, Linework, Layout, and Version Control", "description": "This module connects three-dimensional model thinking to precise two-dimensional drawings and repeatable studio workflows.", "children": [{"id": "5b2f1792-f1a6-4fed-9d61-12fed758da38", "type": "subtopic", "title": "Model organization", "children": [{"id": "5032142d-8271-46da-a8a1-9b5d42bc0126", "type": "concept", "title": "Layers, groups, blocks, components, naming, units, coordinates, and model hygiene"}, {"id": "e8db2529-598d-4a3d-ba8c-a69973713d9e", "type": "concept", "title": "Surface, solid, and mesh logic"}, {"id": "63d0d0e7-78b0-458b-8ad8-f4107e0bed6b", "type": "concept", "title": "Model scope and level of detail"}], "description": "Students learn to build digital models that can generate useful drawings."}, {"id": "9b3dd0f6-d22a-483d-9847-ef688e6ff916", "type": "subtopic", "title": "View extraction", "children": [{"id": "03ed4c37-8736-4da7-8be2-2cdafc518d0c", "type": "concept", "title": "Plans, sections, elevations, axonometrics, perspectives, clipping planes, and make2D/export workflows"}, {"id": "1f29b02b-6e5b-445a-8025-4423388fe24e", "type": "concept", "title": "Linework cleanup and hierarchy"}, {"id": "674ddd14-1062-40e8-bd7f-f1705619833c", "type": "concept", "title": "Model-to-layout coordination"}], "description": "The gist is to translate models into clear architectural drawings."}, {"id": "dacd9dff-dc7b-4fc0-b2e9-b7e78a1af1f2", "type": "subtopic", "title": "Version control habits", "children": [{"id": "e7dfe495-e57a-4bf5-8b96-c2046c13119c", "type": "concept", "title": "File naming, dated versions, backups, linked files, package folders, and export records"}, {"id": "0131c3d3-4c15-452e-9e50-3764bfb70adf", "type": "concept", "title": "Iteration logs and review submissions"}, {"id": "08f3419e-7fa2-4fe1-97ad-601a67abb5f7", "type": "concept", "title": "Collaboration and authorship clarity"}], "description": "Students protect design work from chaos."}]}, {"id": "cbfcc5e9-d3ad-4c65-9706-69531b99b7f5", "type": "topic", "title": "Large-Scale, Experimental, and Atmospheric Drawing", "description": "Students expand drawing beyond small exercises into immersive, atmospheric, and exploratory formats that can stand as design research.", "children": [{"id": "1b4d3a5c-924c-47e1-9c7a-25e06cf007c6", "type": "subtopic", "title": "Scale shift", "children": [{"id": "465d5824-7c9c-4ada-8b64-53923314d9a4", "type": "concept", "title": "Wall drawings, scrolls, composite sheets, oversized perspectives, and room-scale maps"}, {"id": "ce4829c8-4187-48dd-8c36-27910105d711", "type": "concept", "title": "Gesture, movement, and material force"}, {"id": "be7c9360-c2c6-437b-bfde-d5ce68c04250", "type": "concept", "title": "Viewing distance and installation context"}], "description": "Students learn how large drawings change body, gesture, and interpretation."}, {"id": "3b223499-aaa6-4611-b2d8-8a9e99eef298", "type": "subtopic", "title": "Atmospheric drawing", "children": [{"id": "523ba696-0d08-40af-8960-f259c97455cd", "type": "concept", "title": "Air, light, sound, weather, time, occupation, memory, and mood"}, {"id": "fa1ce46d-593e-489e-a34f-9574c57ce584", "type": "concept", "title": "Soft edges, gradients, erasure, layering, and ambiguity"}, {"id": "23c40e3d-f96b-41bf-b6ee-98994c0fe20c", "type": "concept", "title": "Atmosphere tied to architectural intention"}], "description": "The point is to represent qualities that technical drawings often miss."}, {"id": "43760601-6891-4010-a67d-f5f5f8f78850", "type": "subtopic", "title": "Drawing as final work", "children": [{"id": "438d9473-ad1f-47e4-b451-2754ed5ac9ac", "type": "concept", "title": "Series, sequencing, conceptual consistency, craft, and exhibition"}, {"id": "415382d2-9176-458a-b424-f767da9de45b", "type": "concept", "title": "Drawing independent of building proposal"}, {"id": "15d27c30-635e-46d5-918c-c2d998099fa0", "type": "concept", "title": "Critique criteria for experimental work"}], "description": "Students treat drawing as a complete design artifact."}]}, {"id": "3ec1f91a-a339-4573-ba2c-09c4ff0ff091", "type": "topic", "title": "Graphic Hierarchy, Annotation, Typography, Color Systems, and Presentation Composition", "description": "This topic builds communication discipline so drawings, labels, images, and layouts guide an audience clearly through a project.", "children": [{"id": "20aa6f56-921e-4859-95